// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(uint256 initialSum, uint256 newSum) public {
        // Freeze the contract: no initialization parameters are mutable afterwards
        vm.prank(address(1));
        c.SetMinSum(initialSum);
        vm.prank(address(1));
        c.Initialized();

        // A later SetMinSum must revert and leave MinSum unchanged
        vm.prank(address(2));
        bool ok;
        try c.SetMinSum(newSum) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == initialSum);
    }
}
